{{ config(
            materialized='table',
                post_hook={
                    "sql": "WITH sessions AS ( SELECT DATE(Day) AS date, EXTRACT(HOUR FROM Hour) AS hour_num, LPAD(CAST(EXTRACT(HOUR FROM Hour) AS STRING), 2, \'0\') || \':00 - \' || LPAD(CAST(EXTRACT(HOUR FROM Hour) AS STRING), 2, \'0\') || \':59\' AS hour_range, `Landing page path` AS landing_page_path, `Landing page type` AS landing_page_type, `UTM campaign` AS utm_campaign, `UTM content` AS utm_content, `UTM medium` AS utm_medium, `UTM source` AS utm_source, `UTM term` AS utm_term, CAST(`Online store visitors` AS INT64) AS online_store_visitors, CAST(`Sessions` AS INT64) AS session_count, CAST(`Sessions with cart additions` AS INT64) AS sessions_with_cart_additions FROM `beastlife-wh-474411.GCS.Shopify_Sessions_Past` UNION ALL SELECT PARSE_DATE(\'%d-%m-%Y\', Day) AS date, EXTRACT(HOUR FROM PARSE_DATETIME(\'%d-%m-%Y %H:%M\', Hour)) AS hour_num, LPAD(CAST(EXTRACT(HOUR FROM PARSE_DATETIME(\'%d-%m-%Y %H:%M\', Hour)) AS STRING), 2, \'0\') || \':00 - \' || LPAD(CAST(EXTRACT(HOUR FROM PARSE_DATETIME(\'%d-%m-%Y %H:%M\', Hour)) AS STRING), 2, \'0\') || \':59\' AS hour_range, landing_page_path, landing_page_type, utm_campaign, utm_content, utm_medium, utm_source, utm_term, CAST(online_store_visitors AS INT64) AS online_store_visitors, CAST(sessions AS INT64) AS session_count, CAST(sessions_with_cart_additions AS INT64) AS sessions_with_cart_additions FROM `beastlife-wh-474411.maplemonk.beastlife_db_Sessions_Current` ), calendar AS ( SELECT PARSE_DATE(\'%Y-%m-%d\', event_date) AS event_date, Event, sub_event, FORMAT_DATE(\'%Y%m%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateAsInteger, FORMAT_DATE(\'%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateNumber, EXTRACT(YEAR FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS Year, FORMAT_DATE(\'%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNumber, FORMAT_DATE(\'%Y/%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthNumber, FORMAT_DATE(\'%Y/%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthShort, FORMAT_DATE(\'%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameShort, FORMAT_DATE(\'%B\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameLong, EXTRACT(DAYOFWEEK FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekNumber, FORMAT_DATE(\'%A\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeek, FORMAT_DATE(\'%a\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekShort, CONCAT(\'Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS Quarter, CONCAT( FORMAT_DATE(\'%Y\', PARSE_DATE(\'%Y-%m-%d\', event_date)), \'/Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING) ) AS YearQuarter, CASE WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 1 AND 7 THEN \'W1\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 8 AND 14 THEN \'W2\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 15 AND 21 THEN \'W3\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 22 AND 28 THEN \'W4\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) >= 29 THEN \'W5\' ELSE \'Error\' END AS WeekPeriod FROM `beastlife-wh-474411.maplemonk.beastlife_db_Calender` ) SELECT s.*, c.*, t2.SKU, t2.f0_, t2.Type, COALESCE(t2.Category, \'Others\') AS Category, t2.landingPage FROM sessions s LEFT JOIN calendar c ON s.date = c.event_date LEFT JOIN `beastlife-wh-474411.maplemonk.Beastlife_db_Landing_Page` t2 ON LOWER(s.landing_page_path) = LOWER(t2.landingPage);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
